public class SubsetSearch {

    public static void main(String[] args) {
        int[] arr = {1, 2, 3};
        int n = arr.length;
        int target = 3;

        for (int mask = 0; mask < (1 << n); mask++) {
            int sum = 0;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0)
                    sum += arr[j];
            }
            if (sum == target) {
                System.out.print("{ ");
                for (int j = 0; j < n; j++)
                    if ((mask & (1 << j)) != 0)
                        System.out.print(arr[j] + " ");
                System.out.println("}");
            }
        }
        // 출력: { 3 }  { 1 2 }
    }
}
